using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders; using Todo.Api.Models;
namespace Todo.Api.Data;
public sealed class TodoTaskConfiguration : IEntityTypeConfiguration<TodoTask> { public void Configure(EntityTypeBuilder<TodoTask> b) { b.HasKey(x => x.Id); b.Property(x => x.Title).HasMaxLength(200).IsRequired(); b.Property(x => x.Description).HasMaxLength(2000); b.Property(x => x.Category).HasMaxLength(80); b.Property(x => x.Priority).HasMaxLength(30); b.HasIndex(x => x.DueDateUtc); } }
public sealed class DailyLogConfiguration : IEntityTypeConfiguration<DailyLog> { public void Configure(EntityTypeBuilder<DailyLog> b) { b.HasKey(x => x.Date); b.Property(x => x.ProductivityScore).HasPrecision(4, 1); b.Property(x => x.Note).HasMaxLength(2000); } }
public sealed class FoodProductConfiguration : IEntityTypeConfiguration<FoodProduct> { public void Configure(EntityTypeBuilder<FoodProduct> b) { b.HasKey(x => x.Id); b.Property(x => x.Name).HasMaxLength(160).IsRequired(); b.HasIndex(x => x.Name); } }
public sealed class MealEntryConfiguration : IEntityTypeConfiguration<MealEntry> { public void Configure(EntityTypeBuilder<MealEntry> b) { b.HasKey(x => x.Id); b.Property(x => x.MealType).HasMaxLength(40).IsRequired(); b.Property(x => x.WeightGrams).HasPrecision(10, 2); b.Property(x => x.CalculatedCalories).HasPrecision(10, 2); b.Property(x => x.CalculatedProtein).HasPrecision(10, 2); b.Property(x => x.CalculatedFat).HasPrecision(10, 2); b.Property(x => x.CalculatedCarbs).HasPrecision(10, 2); b.HasOne(x => x.Product).WithMany().HasForeignKey(x => x.ProductId).OnDelete(DeleteBehavior.Restrict); b.HasIndex(x => x.Date); } }
public sealed class UserSettingsConfiguration : IEntityTypeConfiguration<UserSettings> { public void Configure(EntityTypeBuilder<UserSettings> b) { b.HasKey(x => x.Id); b.Property(x => x.ThemeMode).HasMaxLength(20); } }
